   113|/** Owner rule 5 — the four mandatory proof fields for VERIFIED. */
   114|export type IVXEngineeringEvidence = {
   115|  commitSha: string | null;
   116|  renderDeployId: string | null;
   117|  testResults: string | null;
   118|  healthVerification: string | null;
