   127|
   128|export function evaluateVerifiedEvidence(
   129|  evidence: Partial<IVXEngineeringEvidence> | null | undefined,
   130|): { complete: boolean; missing: string[] } {
   131|  const missing: string[] = [];
   132|  const has = (value: unknown): boolean => typeof value === 'string' && value.trim().length > 0;
   133|  if (!has(evidence?.commitSha)) missing.push('commitSha');
   134|  if (!has(evidence?.renderDeployId)) missing.push('renderDeployId');
   135|  if (!has(evidence?.testResults)) missing.push('testResults');
   136|  if (!has(evidence?.healthVerification)) missing.push('healthVerification');
   137|  return { complete: missing.length === 0, missing };
