   139|
   140|export type IVXStageTransitionInput = {
   141|  fromStage: IVXEngineeringStage;
   142|  toStage: IVXEngineeringStage;
   143|  actorTeamId: string;
   144|  ownerApproved: boolean;
   145|  evidence: Partial<IVXEngineeringEvidence> | null;
   146|};
   147|
   148|export type IVXStageTransitionResult = {
   149|  allowed: boolean;
   150|  blocker:
   151|    | 'PIPELINE_ORDER_VIOLATION'
   152|    | 'OWNER_APPROVAL_REQUIRED'
   153|    | 'RELEASE_MANAGER_ONLY'
   154|    | 'VERIFIED_EVIDENCE_INCOMPLETE'
   155|    | null;
   156|  detail: string | null;
   157|  missingEvidence: string[];
   158|};
   159|
   160|/**
   161| * Enforces the owner's continuous-loop rules for a single stage transition.
   162| * Deterministic and side-effect free (the emergency-stop check happens in the
   163| * persistence layer where async I/O is allowed).
   164| */
   165|export function evaluateStageTransition(input: IVXStageTransitionInput): IVXStageTransitionResult {
   166|  const fromIndex = IVX_ENGINEERING_PIPELINE.indexOf(input.fromStage);
   167|  const toIndex = IVX_ENGINEERING_PIPELINE.indexOf(input.toStage);
   168|
   169|  if (fromIndex < 0 || toIndex < 0 || toIndex !== fromIndex + 1) {
   170|    return {
   171|      allowed: false,
   172|      blocker: 'PIPELINE_ORDER_VIOLATION',
   173|      detail: `Tasks move one stage at a time in pipeline order; ${input.fromStage} → ${input.toStage} is not the next step.`,
   174|      missingEvidence: [],
   175|    };
   176|  }
   177|
   178|  if (input.toStage === 'PRODUCTION_DEPLOY') {
   179|    if (!input.ownerApproved) {
   180|      return {
   181|        allowed: false,
   182|        blocker: 'OWNER_APPROVAL_REQUIRED',
   183|        detail: 'No production deployment without recorded owner approval (owner rule 6).',
   184|        missingEvidence: [],
   185|      };
   186|    }
   187|    if (input.actorTeamId !== IVX_RELEASE_MANAGER_TEAM_ID) {
   188|      return {
   189|        allowed: false,
   190|        blocker: 'RELEASE_MANAGER_ONLY',
   191|        detail: `Only ${IVX_RELEASE_MANAGER_TEAM_ID} (Release Manager AI) may merge, tag or deploy; actor was ${input.actorTeamId || 'unknown'}.`,
   192|        missingEvidence: [],
   193|      };
   194|    }
   195|  }
   196|
   197|  if (input.toStage === 'PROOF_LEDGER' || input.toStage === 'MONITOR') {
   198|    const proof = evaluateVerifiedEvidence(input.evidence);
   199|    if (!proof.complete) {
   200|      return {
   201|        allowed: false,
   202|        blocker: 'VERIFIED_EVIDENCE_INCOMPLETE',
   203|        detail: `VERIFIED requires GitHub commit SHA, Render deployment id, automated test results and live health verification (owner rule 5). Missing: ${proof.missing.join(', ')}.`,
   204|        missingEvidence: proof.missing,
   205|      };
   206|    }
   207|  }
   208|
   209|  return { allowed: true, blocker: null, detail: null, missingEvidence: [] };
   210|}
   211|
   212|/** The task status a stage implies (used when persisting an advance). */
   213|export function statusForStage(
   214|  stage: IVXEngineeringStage,
   215|  evidence: Partial<IVXEngineeringEvidence> | null,
   216|): IVXEngineeringTaskStatus {
   217|  if (stage === 'OWNER_APPROVAL') return 'WAITING_APPROVAL';
   218|  if (stage === 'MONITOR') {
   219|    return evaluateVerifiedEvidence(evidence).complete ? 'VERIFIED' : 'BLOCKED';
   220|  }
   221|  return 'RUNNING';
   222|}
