   224|// ---------------------------------------------------------------------------
   225|// Persistence (Supabase REST, service-role — server-only)
   226|// ---------------------------------------------------------------------------
   227|
   228|const REST_TIMEOUT_MS = 12_000;
   229|
   230|function supabaseUrl(): string {
   231|  for (const name of ['IVX_SUPABASE_URL', 'SUPABASE_URL', 'EXPO_PUBLIC_SUPABASE_URL']) {
   232|    const value = (process.env[name] ?? '').trim();
   233|    if (value.startsWith('https://')) return value.replace(/\/$/, '');
   234|  }
   235|  return '';
   236|}
   237|
   238|function serviceRoleKey(): string {
   239|  return (process.env.SUPABASE_SERVICE_ROLE_KEY ?? '').trim();
   240|}
   241|
   242|async function restCall(path: string, init: RequestInit): Promise<{ status: number | null; body: string }> {
   243|  const base = supabaseUrl();
   244|  const key = serviceRoleKey();
   245|  if (!base || !key) return { status: null, body: 'supabase service credentials missing in runtime' };
   246|  try {
   247|    const response = await fetch(`${base}${path}`, {
   248|      ...init,
   249|      headers: {
   250|        apikey: key,
   251|        Authorization: `Bearer ${key}`,
   252|        'Content-Type': 'application/json',
   253|        Prefer: 'return=representation',
   254|        ...(init.headers ?? {}),
   255|      },
   256|      signal: AbortSignal.timeout(REST_TIMEOUT_MS),
   257|    });
   258|    return { status: response.status, body: (await response.text()).slice(0, 20_000) };
   259|  } catch (error: unknown) {
   260|    return { status: null, body: error instanceof Error ? error.message.slice(0, 200) : 'fetch failed' };
   261|  }
   262|}
   263|
   264|function parseRows<T>(body: string): T[] {
   265|  try {
   266|    const parsed = JSON.parse(body) as unknown;
   267|    return Array.isArray(parsed) ? (parsed as T[]) : [];
   268|  } catch {
   269|    return [];
   270|  }
   271|}
