   273|export type IVXEngineeringTaskRow = {
   274|  id: string;
   275|  title: string;
   276|  detail: string | null;
   277|  team_id: string;
   278|  stage: IVXEngineeringStage;
   279|  status: IVXEngineeringTaskStatus;
