   290|/** Upserts the 12-team registry into ivx_engineering_teams. */
   291|export async function syncEngineeringTeams(): Promise<{ ok: boolean; upserted: number; error: string | null }> {
   292|  const rows = IVX_ENGINEERING_TEAMS.map((entry) => ({
   293|    team_id: entry.teamId,
   294|    name: entry.name,
   295|    mission: entry.mission,
   296|    focus: entry.focus,
   297|    continuous: entry.continuous,
   298|    can_merge: entry.canMerge,
   299|    can_tag: entry.canTag,
   300|    can_deploy: entry.canDeploy,
   301|    status: entry.status,
   302|  }));
   303|  const result = await restCall('/rest/v1/ivx_engineering_teams?on_conflict=team_id', {
   304|    method: 'POST',
   305|    headers: { Prefer: 'resolution=merge-duplicates,return=representation' },
   306|    body: JSON.stringify(rows),
   307|  });
   308|  if (result.status !== 201 && result.status !== 200) {
   309|    return { ok: false, upserted: 0, error: `HTTP ${result.status ?? 'ERR'}: ${result.body.slice(0, 200)}` };
   310|  }
   311|  return { ok: true, upserted: parseRows(result.body).length, error: null };
   312|}
