   325|export async function getEngineeringTask(taskId: string): Promise<IVXEngineeringTaskRow | null> {
   326|  const result = await restCall(`/rest/v1/ivx_engineering_tasks?id=eq.${encodeURIComponent(taskId)}&select=*&limit=1`, { method: 'GET' });
