   330|export async function createEngineeringTask(input: {
   331|  title: string;
   332|  detail?: string | null;
   333|  teamId: string;
   334|  createdBy?: string | null;
   335|}): Promise<{ ok: boolean; task: IVXEngineeringTaskRow | null; error: string | null }> {
   336|  const title = input.title.trim();
   337|  if (!title) return { ok: false, task: null, error: 'A task title is required.' };
   338|  const knownTeam = IVX_ENGINEERING_TEAMS.some((entry) => entry.teamId === input.teamId);
   339|  if (!knownTeam) return { ok: false, task: null, error: `Unknown team '${input.teamId}'. Valid teams: TEAM-01..TEAM-12.` };
   340|
   341|  const result = await restCall('/rest/v1/ivx_engineering_tasks', {
   342|    method: 'POST',
   343|    body: JSON.stringify({
   344|      title: title.slice(0, 500),
   345|      detail: input.detail?.trim().slice(0, 8000) ?? null,
   346|      team_id: input.teamId,
