   359|export async function recordEngineeringEvidence(input: {
   360|  taskId: string;
   361|  evidence: Partial<IVXEngineeringEvidence>;
   362|}): Promise<{ ok: boolean; task: IVXEngineeringTaskRow | null; error: string | null }> {
   363|  const existing = await getEngineeringTask(input.taskId);
