   367|    method: 'PATCH',
   368|    body: JSON.stringify({ evidence: merged, updated_at: new Date().toISOString() }),
   369|  });
   370|  if (result.status !== 200) {
   371|    return { ok: false, task: null, error: `HTTP ${result.status ?? 'ERR'}: ${result.body.slice(0, 200)}` };
   372|  }
   373|  return { ok: true, task: parseRows<IVXEngineeringTaskRow>(result.body)[0] ?? null, error: null };
