   393|  });
   394|  if (result.status !== 200) {
   395|    return { ok: false, task: null, error: `HTTP ${result.status ?? 'ERR'}: ${result.body.slice(0, 200)}` };
   396|  }
   397|  return { ok: true, task: parseRows<IVXEngineeringTaskRow>(result.body)[0] ?? null, error: null };
