   399|
   400|export async function advanceEngineeringTask(input: {
   401|  taskId: string;
   402|  toStage: IVXEngineeringStage;
   403|  actorTeamId: string;
   404|}): Promise<{ ok: boolean; task: IVXEngineeringTaskRow | null; blocker: string | null; detail: string | null }> {
   405|  const existing = await getEngineeringTask(input.taskId);
   406|  if (!existing) return { ok: false, task: null, blocker: 'TASK_NOT_FOUND', detail: 'Task not found.' };
   407|
   408|  const verdict = evaluateStageTransition({
   409|    fromStage: existing.stage,
   410|    toStage: input.toStage,
   411|    actorTeamId: input.actorTeamId,
   412|    ownerApproved: existing.owner_approved,
   413|    evidence: existing.evidence,
   414|  });
   415|  if (!verdict.allowed) {
   416|    return { ok: false, task: existing, blocker: verdict.blocker, detail: verdict.detail };
   417|  }
   418|
   419|  if (input.toStage === 'PRODUCTION_DEPLOY') {
   420|    const stop = await checkEmergencyStop();
   421|    if (stop.active) {
   422|      return {
   423|        ok: false,
   424|        task: existing,
   425|        blocker: 'EMERGENCY_STOP_ACTIVE',
   426|        detail: 'The owner emergency stop is engaged — production deployment refused.',
   427|      };
   428|    }
   429|  }
   430|
   431|  const nextStatus = statusForStage(input.toStage, existing.evidence);
   432|  const result = await restCall(`/rest/v1/ivx_engineering_tasks?id=eq.${encodeURIComponent(input.taskId)}`, {
   433|    method: 'PATCH',
   434|    body: JSON.stringify({
   435|      stage: input.toStage,
   436|      status: nextStatus,
   437|      blocker: null,
   438|      updated_at: new Date().toISOString(),
   439|    }),
   440|  });
   441|  if (result.status !== 200) {
   442|    return { ok: false, task: existing, blocker: 'PERSISTENCE_FAILED', detail: `HTTP ${result.status ?? 'ERR'}: ${result.body.slice(0, 200)}` };
   443|  }
   444|  return { ok: true, task: parseRows<IVXEngineeringTaskRow>(result.body)[0] ?? existing, blocker: null, detail: null };
